def log_request(self, input_tokens, output_tokens, latency_ms,
                     refusal=False, safety_flag=False, error=False,
                     confidence=None):
    self.metrics['total_requests'] += 1
    if safety_flag:
        self.metrics['safety_flags'] += 1
    if confidence is not None and confidence < 0.7:
        self.metrics['hallucination_suspects'] += 1
        if self.metrics['hallucination_suspects'] > 5:
            self.alerts.append(f'ALERT: {self.metrics["hallucination_suspects"]} low-confidence responses')
